const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
document.querySelector('.mode-tabs').insertAdjacentHTML('beforeend','<button id="market-tab" aria-pressed="false">Marketplace</button>');
const section=document.createElement('section');section.id='market-mode';section.hidden=true;document.querySelector('footer').before(section);
section.innerHTML=`<p class="eyebrow">SECONDHAND & UNIQUE FINDS</p><h1>Good pieces. A second chapter.</h1><p class="intro">Find character, compare pickup options and bring your favorites onto your room board.</p><p class="market-disclosure"><b>Demo listings</b> · Sample inventory from Facebook Marketplace, OfferUp and Craigslist-style feeds. Listings and sellers are fictional.</p><form id="market-filters" class="market-filters"><label>Search<input name="q" placeholder="Walnut, lamp, Austin…" maxlength="100"></label><label>Source<select name="platform"><option value="all">All marketplaces</option><option>Facebook Marketplace</option><option>OfferUp</option><option>Craigslist</option></select></label><label>Category<select name="category"><option value="all">All pieces</option>${['sofa','chair','table','desk','storage','lamp'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Maximum price $<input name="budget" type="number" min="0" value="1000"></label><label><input name="available" type="checkbox" checked> Available only</label><label><input name="portable" type="checkbox"> Portable pieces</label><button class="primary" type="submit">Find pieces</button></form><p id="market-status" role="status"></p><div id="market-results" class="match-grid"></div>`;
for(const m of ['photo','planner','board'])$('#'+m+'-tab').addEventListener('click',()=>{section.hidden=true;$('#market-tab').setAttribute('aria-pressed','false');});
$('#market-tab').onclick=()=>{for(const m of ['photo','planner','board']){$('#'+m+'-mode').hidden=true;$('#'+m+'-tab').setAttribute('aria-pressed','false');}section.hidden=false;$('#market-tab').setAttribute('aria-pressed','true');if(!loaded)search();};
let listings=[],loaded=false,controller;
function artwork(p){let shape=p.shape==='lamp'?`<path d="M155 62h50l18 48h-86z" fill="${p.color}"/><path d="M180 110v90m-32 0h64" stroke="${p.color}" stroke-width="8"/>`:p.shape==='table'?`<ellipse cx="180" cy="115" rx="100" ry="27" fill="${p.color}"/><path d="M180 125v75m-45 0h90" stroke="${p.color}" stroke-width="14"/>`:p.shape==='sofa'||p.shape==='chair'?`<rect x="${p.shape==='chair'?115:65}" y="80" width="${p.shape==='chair'?130:230}" height="100" rx="18" fill="${p.color}"/><rect x="${p.shape==='chair'?100:50}" y="120" width="30" height="65" rx="10" fill="${p.color}"/><rect x="${p.shape==='chair'?230:280}" y="120" width="30" height="65" rx="10" fill="${p.color}"/><path d="M130 180v20m100-20v20" stroke="#67513f" stroke-width="7"/>`:`<rect x="65" y="95" width="230" height="${p.shape==='desk'?18:80}" rx="4" fill="${p.color}"/><path d="M80 113v85m200-85v85" stroke="${p.color}" stroke-width="9"/>`;return `<svg viewBox="0 0 360 240" role="img" aria-label="Illustration of ${escape(p.name)}"><rect width="360" height="240" fill="#ece9df"/><ellipse cx="180" cy="207" rx="125" ry="13" fill="#d8d3c6"/>${shape}<text x="12" y="225" fill="#6c7368" font-size="10">ITEM ILLUSTRATION</text></svg>`;}
async function search(){const form=$('#market-filters');if(!form.reportValidity())return;controller?.abort();controller=new AbortController();const current=controller;const params=new URLSearchParams(new FormData(form));for(const name of ['available','portable'])params.set(name,form.elements[name].checked?'true':'false');$('#market-status').textContent='Finding pieces…';try{const response=await fetch('/api/marketplace?'+params,{signal:current.signal});if(!response.ok)throw Error();const data=await response.json();listings=data.listings;loaded=true;$('#market-status').textContent=listings.length+' pieces nearby';$('#market-results').innerHTML=listings.length?listings.map(p=>`<article class="product">${artwork(p)}<div class="product-body"><p class="eyebrow">${escape(p.platform)} · ${escape(p.status)}</p><h3>${escape(p.name)}</h3><strong class="product-price">${money(p.price)}</strong><p>${escape(p.condition)}</p><p>${escape(p.area)} · ${p.distance} mi from central Austin</p><p>${p.width} × ${p.depth} × ${p.height} in ${p.portable?'· Disassembles for moving':''}</p><details><summary>Seller & pickup details</summary><p>${escape(p.seller)} · Local seller</p><p>Identity and authenticity: not verified.</p><p>Pickup only. Bring suitable transport and confirm access and condition before payment.</p></details><label class="pickup-label">Proposed pickup<select id="pickup-${p.id}"><option value="">Choose later</option>${p.slots.map(s=>`<option>${escape(s)}</option>`).join('')}</select></label><button class="primary" data-market-save="${p.id}" ${p.status!=='Available'?'disabled':''}>${p.status==='Available'?'Save to room board':'Pending · unavailable'}</button><p class="note">Saving a pickup preference does not book a pickup.</p></div></article>`).join(''):'<div class="photo-empty"><h2>No pieces match these filters.</h2><p>Try another source, a broader search or a higher budget.</p></div>';}catch(e){if(e.name!=='AbortError'){$('#market-status').textContent='The marketplace feed could not load. Try searching again.';$('#market-results').innerHTML='';}}}
$('#market-filters').onsubmit=e=>{e.preventDefault();search();};$('#market-results').onclick=e=>{const b=e.target.closest('[data-market-save]');if(!b)return;const p=listings.find(p=>p.id===b.dataset.marketSave);if(!p||p.status!=='Available')return;window.dispatchEvent(new CustomEvent('roomedit-market-save',{detail:{...p,pickupPreference:$('#pickup-'+p.id).value}}));b.textContent='Saved to board';b.disabled=true;$('#market-status').textContent='Saved. Open Room board & move plan to compare costs, fit and household preferences.';};
